## 3. CODIFICAÇÃO EM JAVA

```java
import java.util.*;
import java.io.*;

public class Main {
    static final int SHIFT = 11;
    static final int MASK = (1 << SHIFT) - 1;

    static long encode(int dist, int u, int v) {
        return ((long) dist << (2 * SHIFT)) | ((long) u << SHIFT) | v;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String line = br.readLine();
        if (line == null) return;

        int N = Integer.parseInt(line.trim());
        int[] x = new int[N];
        int[] y = new int[N];

        for (int i = 0; i < N; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            x[i] = Integer.parseInt(st.nextToken());
            y[i] = Integer.parseInt(st.nextToken());
        }

        int totalEdges = N * N; // origem->tenda + todas as tendas entre si
        long[] edges = new long[totalEdges];
        int idx = 0;

        for (int i = 0; i < N; i++) {
            int distOrigin = x[i] * x[i] + y[i] * y[i];
            edges[idx++] = encode(distOrigin, N, i);

            for (int j = 0; j < N; j++) {
                if (i == j) continue;
                int dx = x[i] - x[j];
                int dy = y[i] - y[j];
                int dist = dx * dx + dy * dy;
                edges[idx++] = encode(dist, i, j);
            }
        }

        Arrays.sort(edges);

        int[] best = new int[N];
        int[] tmp = new int[N];
        int[] updated = new int[N];

        int answer = 0;
        int pos = edges.length - 1;

        while (pos >= 0) {
            int currentLen = (int) (edges[pos] >>> (2 * SHIFT));
            int cnt = 0;

            while (pos >= 0 && (int) (edges[pos] >>> (2 * SHIFT)) == currentLen) {
                long e = edges[pos];
                int u = (int) ((e >>> SHIFT) & MASK);
                int v = (int) (e & MASK);

                int dp = 0;
                if (u == N) {
                    dp = 1;
                } else if (best[u] > 0) {
                    dp = best[u] + 1;
                }

                if (dp > 0) {
                    if (dp > tmp[v]) {
                        if (tmp[v] == 0) updated[cnt++] = v;
                        tmp[v] = dp;
                    }
                    if (dp > answer) answer = dp;
                }

                pos--;
            }

            for (int k = 0; k < cnt; k++) {
                int v = updated[k];
                if (tmp[v] > best[v]) best[v] = tmp[v];
                tmp[v] = 0;
            }
        }

        System.out.println(answer);
    }
}
```

